def rle_encode(s: str) -> str:
    if not s:
        return ''

    result = []
    count = 1
    prev_char = s[0]

    for i in range(1, len(s)):
        if s[i] == prev_char:
            count += 1
        else:
            result.append(f"{count}{prev_char}")
            count = 1
            prev_char = s[i]

    result.append(f"{count}{prev_char}")
    return ''.join(result)
