def caesar(s: str, k: int) -> str:
    result = []
    for char in s:
        if char.isalpha():
            if char.isupper():
                shifted = (ord(char) - ord('A') + k) % 26
                result.append(chr(ord('A') + shifted))
            else:
                shifted = (ord(char) - ord('a') + k) % 26
                result.append(chr(ord('a') + shifted))
        else:
            result.append(char)
    return ''.join(result)
