def eval_rpn(tokens: list) -> int:
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Division truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]
```

