def two_sum_pairs(nums: list, target: int) -> list:
    seen = set()
    pairs = set()
    for num in nums:
        complement = target - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)
    return sorted(list(pairs))
