def next_permutation(nums: list) -> list:
    if not nums or len(nums) <= 1:
        return sorted(nums)

    n = len(nums)
    # Step 1: Find the first index i from the right where nums[i] < nums[i+1]
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1

    # If no such index exists, the array is in descending order, so reverse it to get the smallest permutation
    if i == -1:
        return sorted(nums)

    # Step 2: Find the smallest element to the right of i that is greater than nums[i]
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1

    # Step 3: Swap nums[i] and nums[j]
    nums[i], nums[j] = nums[j], nums[i]

    # Step 4: Reverse the elements from i+1 to the end
    nums[i + 1:] = reversed(nums[i + 1:])

    return nums
```

